    // ── multipart-file-part-contenttype-from-extension (behavior 4) ──
    //
    // End-to-end through serialize_multipart_body (the serializer the generated
    // operations actually drive): a file (`MultipartValue::Bytes`) part MUST set
    // its part Content-Type from the field-name extension, falling back to
    // application/octet-stream when the extension is unknown/missing. The field
    // name doubles as the filename, mirroring the other 11 SDKs.

    #[test]
    fn test_multipart_file_part_content_type_png_from_extension() {
        let mut fields = std::collections::HashMap::new();
        fields.insert(
            "avatar.png".to_string(),
            MultipartValue::Bytes(vec![0x89, 0x50, 0x4e, 0x47]),
        );
        let body = serialize_multipart_body(&fields, "BOUNDARY");
        let body_str = String::from_utf8_lossy(&body);
        assert!(
            body_str.contains("Content-Type: image/png\r\n"),
            "png file part must derive image/png Content-Type, got: {}",
            body_str
        );
    }

    #[test]
    fn test_multipart_file_part_content_type_json_from_extension() {
        let mut fields = std::collections::HashMap::new();
        fields.insert(
            "data.json".to_string(),
            MultipartValue::Bytes(b"{}".to_vec()),
        );
        let body = serialize_multipart_body(&fields, "BOUNDARY");
        let body_str = String::from_utf8_lossy(&body);
        assert!(
            body_str.contains("Content-Type: application/json\r\n"),
            ".json file part must derive application/json Content-Type, got: {}",
            body_str
        );
    }

    #[test]
    fn test_multipart_file_part_content_type_unknown_extension_falls_back() {
        let mut fields = std::collections::HashMap::new();
        fields.insert("file".to_string(), MultipartValue::Bytes(vec![1, 2, 3]));
        let body = serialize_multipart_body(&fields, "BOUNDARY");
        let body_str = String::from_utf8_lossy(&body);
        assert!(
            body_str.contains("Content-Type: application/octet-stream\r\n"),
            "extension-less file part must fall back to application/octet-stream, got: {}",
            body_str
        );
    }

    // Raw-bytes part with no explicit filename: the field name is reused as the
    // filename and the Content-Type falls back to application/octet-stream when
    // the field name carries no (known) extension. Mirrors the cross-language
    // contract already implemented by go, node, and java.
    #[test]
    fn test_multipart_raw_bytes_part_reuses_field_name_as_filename_and_octet_stream() {
        let mut fields = std::collections::HashMap::new();
        fields.insert(
            "file".to_string(),
            MultipartValue::Bytes(vec![0x00, 0x01, 0x02]),
        );
        let body = serialize_multipart_body(&fields, "BOUNDARY");
        let body_str = String::from_utf8_lossy(&body);
        assert!(
            body_str.contains("name=\"file\"; filename=\"file\""),
            "raw-bytes part must reuse the field name as the filename, got: {}",
            body_str
        );
        assert!(
            body_str.contains("Content-Type: application/octet-stream\r\n"),
            "raw-bytes part with no extension must use application/octet-stream, got: {}",
            body_str
        );
    }

    // ── multipart-model-part-serialized-through-configured-serializer ──
    //
    // Cross-SDK parity: the addPetPhotos operation sends a multipart/form-data
    // body whose `metadata` part is a MODEL (PhotoMetadata). The generated
    // operation builds that part with exactly the call exercised below —
    // `MultipartValue::Json(object_serializer::serialize(&metadata)?)` — so the
    // model part is encoded through the SDK's CONFIGURED serializer. That means
    // the part JSON carries the WIRE property names declared by the schema
    // (`isPrimary`, `takenAt`) rather than the snake_case Rust field idents
    // (`is_primary`, `taken_at`), and the `format: date-time` field is rendered
    // with chrono's RFC 3339 wire form (millisecond fraction preserved). The
    // object part also advertises `Content-Type: application/json` (its OAS
    // `encoding.contentType`) so the server parses it as JSON, not text/plain.
    // This test reconstructs the operation's part-building path end-to-end
    // through `serialize_multipart_body` (the lowest-level multipart writer the
    // operation ultimately drives) and asserts on the captured body bytes.
    #[test]
    fn test_multipart_model_part_uses_wire_property_names_and_datetime_format() {
        use chrono::{DateTime, Utc};

        // Build a PhotoMetadata exactly as a caller of add_pet_photos would,
        // with the canonical millisecond-precision instant.
        let taken_at: DateTime<Utc> = "2020-01-02T03:04:05.123Z"
            .parse()
            .expect("reference instant must parse");
        let metadata = PhotoMetadata {
            caption: None,
            is_primary: Some(true),
            taken_at: Some(taken_at),
            location: None,
        };

        // Serialize the model part through the CONFIGURED serializer — the same
        // call the generated add_pet_photos emits — then wrap it as the JSON
        // object part the operation hands to the multipart writer.
        let part_json = object_serializer::serialize(&metadata)
            .expect("model part must serialize through the configured serializer");
        let mut fields = std::collections::HashMap::new();
        fields.insert("metadata".to_string(), MultipartValue::Json(part_json));
        let body = serialize_multipart_body(&fields, "BOUNDARY");
        let body_str = String::from_utf8_lossy(&body);

        // (1) The model part must use the WIRE property names from the schema,
        // never the snake_case Rust field idents.
        assert!(
            body_str.contains("\"isPrimary\""),
            "model part must use the wire key `isPrimary`, body: {}",
            body_str
        );
        assert!(
            body_str.contains("\"takenAt\""),
            "model part must use the wire key `takenAt`, body: {}",
            body_str
        );
        assert!(
            !body_str.contains("is_primary"),
            "model part must NOT leak the snake_case ident `is_primary`, body: {}",
            body_str
        );
        assert!(
            !body_str.contains("taken_at"),
            "model part must NOT leak the snake_case ident `taken_at`, body: {}",
            body_str
        );

        // (2) The `format: date-time` field must carry the proper RFC 3339
        // wire form, with millisecond precision preserved (not truncated).
        assert!(
            body_str.contains("2020-01-02T03:04:05.123"),
            "takenAt must serialize as an RFC 3339 date-time with millis, body: {}",
            body_str
        );

        // (3) The captured part is the part for the `metadata` field —
        // confirm it is wired as a form field (not a file part).
        assert!(
            body_str.contains("name=\"metadata\""),
            "metadata model part must be emitted under the `metadata` field name, body: {}",
            body_str
        );

        // (4) The object part advertises its OAS `encoding.contentType`
        // (`application/json`) so a content-negotiating server parses the JSON
        // rather than treating the part as text/plain.
        assert!(
            body_str.contains("Content-Type: application/json\r\n"),
            "JSON object part must carry a `Content-Type: application/json` header, body: {}",
            body_str
        );
    }

    // ── multipart-non-ascii-field-name-preserved-utf8 (behavior 5) ──
    //
    // A multipart part whose field NAME contains non-ASCII characters MUST emit
    // those characters as raw UTF-8 bytes in the Content-Disposition `name="..."`
    // parameter — never transliterated to `?` nor stripped.

    #[test]
    fn test_multipart_non_ascii_field_name_preserved_as_utf8_text_part() {
        let field_name = "café"; // 'é' is U+00E9 -> UTF-8 0xC3 0xA9
        let mut fields = std::collections::HashMap::new();
        fields.insert(
            field_name.to_string(),
            MultipartValue::Text("v".to_string()),
        );
        let body = serialize_multipart_body(&fields, "BOUNDARY");

        // The raw UTF-8 bytes for "café" must appear verbatim in the body.
        let needle = b"name=\"caf\xC3\xA9\"";
        assert!(
            body.windows(needle.len()).any(|w| w == needle),
            "non-ASCII field name must be emitted as raw UTF-8, body: {:?}",
            String::from_utf8_lossy(&body)
        );
        assert!(
            !body.contains(&b'?'),
            "non-ASCII field name must not be transliterated to '?'"
        );
    }

    #[test]
    fn test_multipart_non_ascii_field_name_preserved_as_utf8_file_part() {
        // CJK field name on a bytes (file) part — must also survive as UTF-8.
        let field_name = "日本.png"; // emits image/png too (behavior 4 cross-check)
        let mut fields = std::collections::HashMap::new();
        fields.insert(field_name.to_string(), MultipartValue::Bytes(vec![0, 1, 2]));
        let body = serialize_multipart_body(&fields, "BOUNDARY");

        let nihon = "日本".as_bytes(); // E6 97 A5 E6 9C AC
        assert!(
            body.windows(nihon.len()).any(|w| w == nihon),
            "CJK field name must be emitted as raw UTF-8 in Content-Disposition"
        );
        let body_str = String::from_utf8_lossy(&body);
        assert!(
            body_str.contains("Content-Type: image/png\r\n"),
            "non-ASCII .png file name must still derive image/png, got: {}",
            body_str
        );
    }

